types.text:
type BannerAction = {
  id: string;
  label: string;
  onAction: () => void;
};

type BannerLink = {
  label: string;
  href: string;
};

type BannerOwnProps = {
  title?: React.ReactNode;
  icon?: React.ReactNode;
  tone?: BannerTone;
  emphasis?: BannerEmphasis;
  customColor?: string;
  align?: BannerAlign;
  actions?: readonly BannerAction[];
  link?: BannerLink;
  dismissible?: boolean;
  dismissed?: boolean;
  defaultDismissed?: boolean;
  onDismiss?: () => void;
  dismissLabel?: string;
  label?: string;
  alert?: boolean;
};
